```rust
/// What the pure parser knows from the JSON plus (optionally) the schema.
pub struct DdocMeta {
    pub address: String,              // positional dd address: "file#section/id" (or with a map key)
    pub schema: String,               // dd.schema, verbatim; "" when absent
    pub trail: Vec<String>,           // ["section", "<map key>"?, "id"] - the parent trail
    pub section: String,
    pub id: String,
    pub id_kind: Option<IdKind>,      // parsed from the minted prefix; None for an unregistered id
    pub state: Option<String>,        // the row's STORED state, verbatim. Never trusted alone.
    pub gate_terminal: Option<bool>,  // membership of the schema's gate_terminal set; None = unknown
    pub derived_state: Option<DerivedState>,
    pub doc_title: Option<String>,
    pub sweep_excluded: bool,
    pub embed_basis: EmbedBasis,      // how raw_text was chosen - schema-declared or fallback
    pub rels: Vec<DdocRel>,           // filled by the adapter (u2); empty from the parser alone
    pub findings: Vec<String>,        // validate findings; a broken doc is still indexed
}

pub enum IdKind { Phase, Task, AcceptanceCriterion, Backpressure, LogEntry, DoneWhen, Finding, Friction, Verdict }

pub enum EmbedBasis { SchemaDeclared, Fallback }

/// Stored vs derived are SEPARATE CLAIMS and dd does not reconcile them.
pub struct DerivedState { pub complete: bool, pub incomplete: Vec<String> }

pub struct DdocRel { pub rel: String, pub target: String, pub kind: String, pub location: String }

/// Facts read out of `ddocs --json schema show`, handed to the pure parser by the shell.
pub struct DdocSchemaFacts {
    pub schema: String,
    pub prose_fields: BTreeMap<String, Vec<String>>,   // section -> fields declared `text`
    pub string_fields: BTreeMap<String, Vec<String>>,  // section -> fields declared `string`
    pub gate_terminal: BTreeSet<String>,
}

pub struct DdocAddress { pub file: String, pub trail: Vec<String> }
impl DdocAddress {
    pub fn parse(text: &str) -> Result<Self, DdocAddressError>;
    pub fn render(&self) -> String;
}

/// The ONE derived-state function. dd's rule, ported because dd cannot expose it today:
/// incomplete = ids whose state is outside gate_terminal; complete = incomplete.is_empty().
pub fn derive_state<'a>(
    entries: impl Iterator<Item = (&'a str, Option<&'a str>)>,
    gate_terminal: &BTreeSet<String>,
) -> DerivedState;
```

